def shortest_path(graph, start, end):
    if start == end:
        return [start]
    stack = [(start, [start])]
    seen = set()
    while stack:
        node, path = stack.pop(0)
        if node == end:
            return path
        if node in seen:
            continue
        seen.add(node)
        for neighbor in graph.get(node, []):
            stack.append((neighbor, path + [neighbor]))
    return []

