def split_escaped(text):
    result = []
    current = []
    i = 0
    while i < len(text):
        if text[i] == '\\':
            if i + 1 < len(text):
                current.append(text[i + 1])
                i += 2
            else:
                raise ValueError("Trailing backslash")
        elif text[i] == '|':
            result.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(text[i])
            i += 1
    result.append(''.join(current))
    return result
